INSERT INTO public.beta_settings (key, value, updated_at) VALUES
	('admission', 'open', '2026-11-04 18:26:16.95974+00');
INSERT INTO public.topics (id, name, exam_weight_min, exam_weight_max, default_sequence, summary, created_at) VALUES
	('quant', 'Quantitative Methods', 11.0, 14.0, 2, 'The mathematics the rest of the syllabus assumes: time value of money, distributions, and inference.', '2026-09-07 19:56:50.122004+00'),
	('econ', 'Economics', 6.0, 9.0, 3, 'Microeconomic behaviour, macroeconomic aggregates, policy, and exchange rates.', '2026-09-07 19:56:50.122004+00'),
	('fsa', 'Financial Statement Analysis', 11.0, 14.0, 4, 'Reading and interrogating the three statements, and the judgement behind the numbers.', '2026-09-07 19:56:50.122004+00'),
	('ci', 'Corporate Finance', 6.0, 9.0, 5, 'How firms are governed, funded, and how they choose between investments.', '2026-09-07 19:56:50.122004+00'),
	('eq', 'Equities', 11.0, 14.0, 6, 'Market structure, efficiency, and the valuation of ownership claims.', '2026-09-07 19:56:50.122004+00'),
	('fi', 'Fixed Income', 11.0, 14.0, 7, 'Debt instruments, their pricing, and the sensitivity of that price to rates and credit.', '2026-09-07 19:56:50.122004+00'),
	('deriv', 'Derivatives and Risk Management', 6.0, 9.0, 8, 'Forwards, futures, swaps and options, and the arbitrage logic that prices them.', '2026-09-07 19:56:50.122004+00'),
	('alt', 'Alternative Investments', 6.0, 9.0, 9, 'Private markets, real assets, and hedge funds — their structures, fees, and risks.', '2026-09-07 19:56:50.122004+00'),
	('pm', 'Portfolio Management', 8.0, 12.0, 10, 'Combining assets: risk and return, the efficient frontier, and planning for an investor.', '2026-09-07 19:56:50.122004+00'),
	('eth', 'Ethical and Professional Standards', 10.0, 15.0, 1, 'The Code and Standards, applied to situations rather than recited. One of the most heavily weighted topics on the exam, and the one that decides borderline results — which is why it comes first and is revisited, rather than being left to the end.', '2026-09-07 19:56:50.122004+00');
