	('9d934e74-3379-4345-bc6f-964714374dfb', 'CFA Level I', 2027, 'november', '2027-11-10', '2027-11-16', NULL, false, '2026-09-07 18:36:46.423585+00'),
	('6d459b00-3640-42c7-a5fe-b1f265305773', 'CFA Level I', 2028, 'february', '2028-02-15', '2028-02-21', NULL, false, '2026-09-07 18:36:46.423585+00'),
	('81354d3c-56d8-495b-a0d4-6b1580a0609a', 'CFA Level I', 2028, 'may', '2028-05-10', '2028-05-16', NULL, false, '2026-09-07 18:36:46.423585+00'),
	('66ca3b58-9361-4f3d-a268-10ef2f60441c', 'CFA Level I', 2028, 'august', '2028-08-15', '2028-08-21', NULL, false, '2026-09-07 18:36:46.423585+00'),
	('7e4453d0-5865-4d9f-902e-015117e09f03', 'CFA Level I', 2028, 'november', '2028-11-08', '2028-11-14', NULL, false, '2026-09-07 18:36:46.423585+00');
INSERT INTO public.curriculum_manifests (id, year, level, version, is_active, capabilities, created_at) VALUES
	('11111111-1111-1111-1111-111111111111', 2027, 'CFA Level I', 'v1.0', true, '{"blueprint_available": true, "reviewed_bank_available": true, "live_generation_available": false, "source_guidance_available": true, "explanation_grading_available": false, "deterministic_numerical_verification_available": true}', '2026-09-05 18:01:14.522749+00');
INSERT INTO public.learning_modules (id, topic_id, name, los_count, effort_units, difficulty_weight, created_at, topic_ref, effort_band, sequence_hint, summary, is_active) VALUES
	('r026', 'ci', 'Business Models', 2, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'ci', 2, 7, 'Describes the key features and types of business models.', true),
	('r001', 'quant', 'Returns of Financial Assets and Instruments', 2, 2.01, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 3, 1, 'Defines what a return is and how it is measured on financial assets, instruments and indicators. Builds the language of required return: the risk-free rate, risk premia and inflation.', true),
	('r002', 'quant', 'Types of Financial Returns', 1, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 3, 2, 'Distinguishes the main types of returns across assets, instruments and indicators, and how each is calculated over short and long horizons.', true),
	('r003', 'quant', 'Benchmarking Returns', 2, 3.30, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 4, 3, 'Compares how portfolio performance and market indexes are measured: money-weighted versus time-weighted returns, and how index construction choices shape what an index shows.', true),
	('r004', 'quant', 'The Time Value of Money in Finance', 3, 2.44, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 4, 4, 'Applies discounted cash flow to value fixed-income and equity instruments, and derives implied returns and growth. Introduces cash flow additivity and no-arbitrage pricing.', true),
	('r005', 'quant', 'Statistical Characteristics of Asset Returns', 4, 3.16, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 4, 5, 'Describes return data with measures of central tendency, dispersion, skewness, kurtosis, covariance and correlation.', true),
	('r006', 'quant', 'Statistical Distributions for Financial Asset Prices and Returns', 4, 3.73, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 4, 6, 'Covers expected values, variances and the main probability distributions used for asset prices and returns, including conditional expectations and Bayesian updating.', true),
	('r007', 'quant', 'Estimation and Hypothesis Testing', 3, 5.89, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 4, 7, 'Explains sampling, the central limit theorem, confidence intervals and hypothesis testing, and how to choose between parametric and non-parametric tests.', true),
	('r008', 'quant', 'The Return and Risk of a Financial Portfolio', 3, 5.03, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 4, 8, 'Calculates portfolio return and risk, shows how correlation drives diversification, and builds the efficient frontier, capital allocation line and CAPM.', true),
	('r009', 'quant', 'Simulation of Financial Asset Prices and Returns', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 3, 9, 'Introduces simulation as a way to model uncertain outcomes: historical simulation, bootstrap resampling and Monte Carlo.', true),
	('r010', 'quant', 'Applications of Simple Linear Regression in Finance', 4, 3.73, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 4, 10, 'Uses simple linear regression to relate variables in finance: estimation, assumptions, goodness of fit, prediction intervals and CAPM estimation.', true),
	('r011', 'quant', 'Introduction to Financial Data Science', 1, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'quant', 3, 11, 'Introduces big data, machine learning, artificial intelligence and fintech as they apply to investment management.', true),
	('r012', 'econ', 'The Firm and Market Structures', 5, 3.45, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 4, 1, 'Explains how firms decide output and pricing under different market structures, using breakeven, shutdown and scale ideas, and how structure and concentration are identified.', true),
	('r013', 'econ', 'Understanding Business Cycles', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 3, 2, 'Describes the business cycle and its phases, credit cycles, and how activity across sectors varies over the cycle and is measured.', true),
	('r014', 'econ', 'Fiscal Policy', 4, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 3, 3, 'Compares fiscal with monetary policy, its objectives and tools, the debt debate, and whether a stance is expansionary or contractionary.', true),
	('r015', 'econ', 'Monetary Policy', 4, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 3, 4, 'Covers central bank objectives and tools, the monetary transmission mechanism, inflation targeting and the limits of monetary policy.', true),
	('r016', 'econ', 'Introduction to Geopolitics', 6, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 3, 5, 'Introduces geopolitics: cooperation versus competition, globalization, international organizations, geopolitical risk and its effect on investments.', true),
	('r017', 'econ', 'International Trade', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 3, 6, 'Explains the benefits and costs of international trade, trade restrictions and the trading blocs and unions that shape it.', true),
	('r018', 'econ', 'Capital Flows and the FX Market', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 3, 7, 'Describes the foreign exchange market, exchange rate regimes and their effects, and capital restrictions imposed by governments.', true),
	('r019', 'econ', 'Exchange Rate Calculations', 2, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'econ', 3, 8, 'Teaches exchange rate calculations: cross rates, no-arbitrage relationships, forward rates, points and premium or discount.', true),
	('r020', 'ci', 'Organizational Forms, Corporate Issuer Features, and Ownership', 3, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'ci', 2, 1, 'Compares organizational forms of business and the features of corporate issuers, including public versus private ownership.', true),
	('r021', 'ci', 'Investors and Other Stakeholders', 3, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'ci', 2, 2, 'Compares the claims and motivations of lenders and shareholders, other stakeholder groups, and the ESG factors investors consider.', true),
	('r022', 'ci', 'Corporate Governance: Conflicts, Mechanisms, Risks, and Benefits', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'ci', 3, 3, 'Explains principal-agent conflicts, governance mechanisms, and the risks of poor governance and benefits of effective governance.', true),
	('r023', 'ci', 'Working Capital and Liquidity', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'ci', 3, 4, 'Covers the cash conversion cycle, liquidity levels and the management of working capital.', true),
	('r024', 'ci', 'Capital Investments and Capital Allocation', 4, 2.01, 3.00, '2026-09-19 19:10:18.911572+00', 'ci', 3, 5, 'Covers types of capital investment, NPV, IRR and ROIC, capital allocation principles and pitfalls, and real options.', true),
	('r025', 'ci', 'Capital Structure', 4, 2.01, 3.00, '2026-09-19 19:10:18.911572+00', 'ci', 3, 6, 'Calculates and interprets the weighted-average cost of capital and explains capital structure theories including Modigliani-Miller.', true),
	('r027', 'fsa', 'Introduction to Financial Statement Analysis', 5, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 3, 1, 'Introduces the financial statement analysis framework, the roles of analysis, the information in filings, notes and audit reports, and how reporting standards develop.', true),
	('r028', 'fsa', 'Analyzing Income Statements', 5, 5.17, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 2, 'Analyzes income statements: revenue and expense recognition, non-recurring items, basic and diluted earnings per share, and common-size analysis.', true),
	('r029', 'fsa', 'Analyzing Balance Sheets', 5, 2.30, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 3, 'Analyzes balance sheets: intangible assets, goodwill, financial instruments, non-current liabilities and common-size balance sheets.', true),
	('r030', 'fsa', 'Analyzing Statements of Cash Flows I', 4, 4.31, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 4, 'Explains how the cash flow statement links to the other statements, direct versus indirect preparation, and IFRS versus US GAAP differences.', true),
	('r031', 'fsa', 'Analyzing Statements of Cash Flows II', 2, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 3, 5, 'Analyzes cash flow statements: free cash flow to the firm and to equity, and cash flow ratios.', true),
	('r032', 'fsa', 'Analysis of Inventories', 3, 2.87, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 6, 'Covers inventory measurement, the effect of FIFO and LIFO in inflation and deflation, and presentation and disclosure.', true),
	('r033', 'fsa', 'Analysis of Long-Term Assets', 3, 2.59, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 7, 'Compares reporting of purchased, internally developed and acquired assets, impairment and derecognition, and long-term asset disclosures.', true),
	('r034', 'fsa', 'Topics in Long-Term Liabilities and Equity', 3, 3.45, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 8, 'Covers lease reporting from both sides, defined contribution and benefit plans, share-based compensation and related disclosures.', true),
	('r035', 'fsa', 'Analysis of Income Taxes', 4, 3.16, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 9, 'Explains differences between accounting profit and taxable income, deferred tax assets and liabilities, tax rates and disclosures.', true),
	('r036', 'fsa', 'Financial Reporting Quality', 8, 2.59, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 10, 'Assesses financial reporting quality: the spectrum from conservative to aggressive, earnings management and warning signs of manipulation.', true),
	('r037', 'fsa', 'Financial Analysis Techniques', 6, 4.31, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 4, 11, 'Applies ratio analysis: activity, liquidity, solvency and profitability, DuPont decomposition, industry-specific ratios and forecasting.', true),
	('r038', 'fsa', 'Introduction to Financial Statement Modeling', 5, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fsa', 3, 12, 'Builds a sales-based pro forma model and considers behavioral factors, competitive position and forecast horizon.', true),
	('r039', 'eq', 'Equity Instrument Features', 2, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 2, 1, 'Describes basic features and types of equity instruments and contrasts public with private equity.', true),
	('r040', 'eq', 'Equity Jurisdictions, Classes, and the Voting Process', 2, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 2, 2, 'Explains economic and voting rights across jurisdictions and share classes, and the voting process and its participants.', true),
	('r041', 'eq', 'Equity Issuance and Trading', 4, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 3, 3, 'Describes equity markets, exchanges and trading venues, liquidity measures and types of equity indexes.', true),
	('r042', 'eq', 'Sources of Equity Returns', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 3, 4, 'Explains dividends, share repurchases and splits, and calculates price and total return for equities.', true),
	('r043', 'eq', 'Introduction to Equity Valuation', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 3, 5, 'Contrasts price with intrinsic value, book value with market capitalization and enterprise value, and outlines the main valuation models.', true),
	('r044', 'eq', 'Discounted Cash Flow (DCF) and Growth Models', 4, 2.59, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 4, 6, 'Values equity using discounted cash flow: dividend, FCFF, FCFE and residual income models, constant and multistage growth, and preferred stock.', true),
	('r045', 'eq', 'Relative Value Equity Valuation Approaches', 4, 2.59, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 4, 7, 'Values equity with multiples: price and enterprise value multiples, peer groups and comparable-based valuation.', true),
	('r046', 'eq', 'Financial Statement Forecasting in Equity Valuation', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 3, 8, 'Explains how to construct and evaluate financial statement forecast models for equity valuation.', true),
	('r047', 'eq', 'Industry and Competitive Analysis', 4, 2.30, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 4, 9, 'Describes industry analysis: classification, size, growth and profitability, and structure through Porter''s Five Forces and PESTLE.', true),
	('r048', 'eq', 'Company Analysis: Past, Present, and Future', 3, 2.30, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 4, 10, 'Evaluates a company''s strategy and position, revenue drivers, profitability and pricing power, working capital and capital structure.', true),
	('r049', 'eq', 'Equity Analyst Research Reports', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 3, 11, 'Describes the elements of an equity analyst research report and compares sell-side with buy-side views.', true),
	('r050', 'eq', 'The Capital Asset Pricing Model, Market Model, and Other Factor-Based Equity Models', 2, 1.58, 3.00, '2026-09-19 19:10:18.911572+00', 'eq', 3, 12, 'Estimates the cost of equity with the CAPM and market model, and introduces arbitrage pricing theory and multi-factor models.', true),
	('ci-workingcap', 'ci', 'Working Capital and Liquidity', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'ci', 3, 3, 'The cash conversion cycle, short-term funding, and managing liquidity.', false),
	('r051', 'fi', 'Fixed-Income Instrument Features', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 1, 'Describes the features of a fixed-income security and the contents of a bond indenture, including covenants.', true),
	('r052', 'fi', 'Fixed-Income Cash Flows and Types', 2, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 2, 'Explains fixed-income cash flow structures, contingency provisions, and the legal, regulatory and tax factors that affect issuance and trading.', true),
	('r053', 'fi', 'Fixed-Income Issuance and Trading', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 3, 'Describes fixed-income market segments and participants, index types, and primary versus secondary markets.', true),
	('r054', 'fi', 'Fixed-Income Markets for Corporate Issuers', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 4, 'Compares short- and long-term funding for corporate issuers, including repurchase agreements, and investment-grade versus high-yield funding.', true),
	('r055', 'fi', 'Fixed-Income Markets for Government Issuers', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 5, 'Describes funding by sovereign, non-sovereign and supranational issuers and contrasts government with corporate issuance and trading.', true),
	('r056', 'fi', 'Fixed-Income Bond Valuation: Prices and Yields', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 6, 'Values a bond from yield to maturity, explains price relationships and matrix pricing.', true),
	('r057', 'fi', 'Yield and Yield Spread Measures for Fixed-Rate Bonds', 2, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 7, 'Calculates yields and yield spreads for fixed-rate bonds and interprets them.', true),
	('r058', 'fi', 'Yield and Yield Spread Measures for Floating-Rate Instruments', 2, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 8, 'Calculates spreads and yields for floating-rate instruments and money market instruments.', true),
	('r059', 'fi', 'The Term Structure of Interest Rates: Spot, Par, and Forward Curves', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 9, 'Explains spot, par and forward rates, prices bonds from spot rates, and compares the curves.', true),
	('r060', 'fi', 'Interest Rate Risk and Return', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 10, 'Analyzes sources of return on a fixed-rate bond, holding period return and Macaulay duration.', true),
	('r061', 'fi', 'Yield-Based Bond Duration Measures and Properties', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 11, 'Defines and calculates modified duration, money duration and price value of a basis point, and what drives interest rate risk.', true),
	('r062', 'fi', 'Yield-Based Bond Convexity and Portfolio Properties', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 12, 'Calculates convexity and combines duration and convexity to estimate price change, including at portfolio level.', true),
	('r063', 'fi', 'Curve-Based and Empirical Fixed-Income Risk Measures', 4, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 13, 'Uses effective duration and convexity for bonds with options, key rate duration, and empirical versus analytical duration.', true),
	('r064', 'fi', 'Credit Risk', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 14, 'Describes credit risk and its components, uses and limits of ratings, and drivers of yield spreads.', true),
	('r065', 'fi', 'Credit Analysis for Government Issuers', 1, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 15, 'Explains special considerations in evaluating sovereign and non-sovereign government credit.', true),
	('r066', 'fi', 'Credit Analysis for Corporate Issuers', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 16, 'Describes qualitative and quantitative factors in corporate credit analysis, seniority rankings and claims priority.', true),
	('r067', 'fi', 'Fixed-Income Securitization', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 17, 'Explains the benefits of securitization and the parties and roles involved.', true),
	('r068', 'fi', 'Asset-Backed Security (ABS) Instrument and Market Features', 4, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 2, 18, 'Describes covered bonds, credit enhancement, non-mortgage ABS and collateralized debt obligations.', true),
	('r069', 'fi', 'Mortgage-Backed Security (MBS) Instrument and Market Features', 4, 2.01, 3.00, '2026-09-19 19:10:18.911572+00', 'fi', 3, 19, 'Explains prepayment risk, tranching, residential mortgage loans and commercial and residential mortgage-backed securities.', true),
	('r070', 'deriv', 'Derivative Instrument and Derivative Market Features', 2, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 3, 1, 'Defines a derivative, describes derivative markets and contrasts over-the-counter with exchange-traded contracts.', true),
	('r071', 'deriv', 'Forward Commitment and Contingent Claim Features and Instruments', 3, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 3, 2, 'Defines forwards, futures, swaps, options and credit derivatives, determines option value at expiration, and contrasts forward commitments with contingent claims.', true),
	('r072', 'deriv', 'Derivative Benefits, Risks, and Issuer and Investor Uses', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 2, 3, 'Describes the benefits and risks of derivatives and how issuers and investors use them.', true),
	('r073', 'deriv', 'Arbitrage, Replication, and the Cost of Carry in Pricing Derivatives', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 2, 4, 'Explains arbitrage, replication and cost of carry as foundations of derivative pricing.', true),
	('r074', 'deriv', 'Pricing and Valuation of Forward Contracts and for an Underlying with Varying Maturities', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 2, 5, 'Values forward contracts at initiation, during their life and at expiration, and explains how forward rates are determined.', true),
	('r075', 'deriv', 'Pricing and Valuation of Futures Contracts', 2, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 2, 6, 'Compares the value and price of forward and futures contracts and explains why they differ.', true),
	('r076', 'deriv', 'Pricing and Valuation of Interest Rates and Other Swaps', 2, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 2, 7, 'Explains how swaps resemble and differ from forward contracts and how swaps are priced and valued.', true),
	('r077', 'deriv', 'Pricing and Valuation of Options', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 3, 8, 'Explains exercise value, moneyness and time value, and the factors that determine an option''s value.', true),
	('r078', 'deriv', 'Option Replication Using Put-Call Parity', 2, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 2, 9, 'Explains put-call parity and put-call forward parity for European options.', true),
	('r079', 'deriv', 'Valuing a Derivative Using a One-Period Binomial Model', 2, 1.29, 3.00, '2026-09-19 19:10:18.911572+00', 'deriv', 3, 10, 'Values a derivative with a one-period binomial model and explains risk neutrality.', true),
	('r080', 'alt', 'Alternative Investment Features, Methods, and Structures', 3, 1.44, 3.00, '2026-09-19 19:10:18.911572+00', 'alt', 3, 1, 'Describes features and categories of alternative investments, the ways to invest in them and their ownership and compensation structures.', true),
	('r081', 'alt', 'Alternative Investment Performance and Returns', 2, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'alt', 3, 2, 'Describes performance appraisal of alternative investments and calculates returns before and after fees.', true),
	('r082', 'alt', 'Investments in Private Capital: Equity and Debt', 3, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'alt', 2, 3, 'Explains private equity and private debt features and the diversification benefits of private capital.', true),
	('r083', 'alt', 'Real Estate and Infrastructure', 4, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'alt', 2, 4, 'Explains the features and investment characteristics of real estate and infrastructure.', true),
	('r084', 'alt', 'Natural Resources', 3, 0.86, 3.00, '2026-09-19 19:10:18.911572+00', 'alt', 2, 5, 'Explains raw land, timberland, farmland and commodities and analyzes their risk, return and diversification.', true),
	('r085', 'alt', 'Hedge Funds', 3, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'alt', 2, 6, 'Explains hedge fund features, forms and vehicles, and analyzes risk, return and diversification.', true),
	('r086', 'alt', 'Introduction to Digital Assets', 4, 2.30, 3.00, '2026-09-19 19:10:18.911572+00', 'alt', 4, 7, 'Introduces distributed ledger technology and digital assets, their forms and vehicles, and their risk, return and diversification.', true),
	('r087', 'pm', 'Portfolio Risk and Return: Part I', 7, 2.59, 3.00, '2026-09-19 19:10:18.911572+00', 'pm', 4, 1, 'Covers asset-class characteristics, risk aversion and utility, mean, variance and covariance from historical data, portfolio standard deviation, and the efficient frontiers.', true),
	('r088', 'pm', 'Portfolio Risk and Return: Part II', 9, 3.73, 3.00, '2026-09-19 19:10:18.911572+00', 'pm', 4, 2, 'Combines a risk-free asset with risky assets, explains systematic and nonsystematic risk, beta, the CAPM and SML, and performance ratios.', true),
	('r089', 'pm', 'Portfolio Management: An Overview', 6, 2.01, 3.00, '2026-09-19 19:10:18.911572+00', 'pm', 3, 3, 'Describes the portfolio approach, the portfolio management process, investor types, pension plans and pooled investments.', true),
	('r090', 'pm', 'Basics of Portfolio Planning and Construction', 8, 2.01, 3.00, '2026-09-19 19:10:18.911572+00', 'pm', 3, 4, 'Explains the investment policy statement, risk and return objectives, constraints, asset allocation and ESG considerations.', true),
	('r091', 'pm', 'The Behavioral Biases of Individuals', 3, 2.30, 3.00, '2026-09-19 19:10:18.911572+00', 'pm', 4, 5, 'Compares cognitive errors with emotional biases and their implications for financial decisions.', true),
	('r092', 'pm', 'Introduction to Risk Management', 7, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'pm', 3, 6, 'Defines risk management and its framework, governance, risk tolerance, budgeting, risk sources and methods of measuring and modifying risk.', true),
	('r093', 'eth', 'Ethics and Trust in the Investment Profession', 1, 1.15, 3.00, '2026-09-19 19:10:18.911572+00', 'eth', 2, 1, NULL, true),
