	('r102', 'eth', 'Application of the Code and Standards: Level I', 1, 1.72, 3.00, '2026-09-19 19:10:18.911572+00', 'eth', 3, 10, NULL, true),
	('quant-rates', 'quant', 'Rates, Returns and the Time Value of Money', 1, 4.00, 3.00, '2026-09-07 19:57:13.931703+00', 'quant', 4, 1, 'Interest rate interpretations, present and future value, annuities, and return measures. Almost every other topic leans on this.', false),
	('quant-stats', 'quant', 'Describing Data and Summary Measures', 1, 3.00, 2.00, '2026-09-07 19:57:13.931703+00', 'quant', 3, 2, 'Central tendency, dispersion, skewness and kurtosis, and how a summary can mislead.', false),
	('quant-prob', 'quant', 'Probability and Expected Value', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'quant', 3, 3, 'Conditional and joint probability, Bayes, expected value, covariance and correlation.', false),
	('quant-dist', 'quant', 'Common Probability Distributions', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'quant', 3, 4, 'Normal, lognormal, binomial and uniform distributions, and where each is the right model.', false),
	('quant-sampling', 'quant', 'Sampling and Estimation', 1, 2.00, 3.00, '2026-09-07 19:57:13.931703+00', 'quant', 2, 5, 'Sampling distributions, the central limit theorem, confidence intervals, and sampling bias.', false),
