	('quant-regression', 'quant', 'Simple Linear Regression', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'quant', 3, 7, 'Fitting and interpreting a single-variable regression, and the assumptions behind it.', false),
