	('econ-firm', 'econ', 'The Firm and Market Structures', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'econ', 3, 2, 'Cost curves, returns to scale, and behaviour under perfect competition through monopoly.', false),
	('econ-macro', 'econ', 'Aggregate Output, Prices and Growth', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'econ', 3, 3, 'GDP and its measurement, aggregate demand and supply, and sources of growth.', false),
	('econ-cycles', 'econ', 'Business Cycles and Inflation', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'econ', 3, 4, 'Phases of the cycle, indicators, unemployment, and the measurement of inflation.', false),
	('econ-policy', 'econ', 'Monetary and Fiscal Policy', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'econ', 3, 5, 'Policy tools, transmission, and the limits of each in practice.', false),
	('econ-fx', 'econ', 'Exchange Rates and International Trade', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'econ', 3, 6, 'Quoting conventions, parity relationships, the balance of payments, and trade restrictions.', false),
	('fsa-intro', 'fsa', 'Introduction to Financial Statement Analysis', 3, 2.00, 2.00, '2026-09-05 18:01:14.522749+00', 'fsa', 2, 1, 'The role of the statements, the audit, and the analyst framework applied to them.', false),
	('fsa-income', 'fsa', 'Analyzing the Income Statement', 4, 4.00, 3.00, '2026-09-05 18:01:14.522749+00', 'fsa', 4, 2, 'Revenue and expense recognition, EPS, and the judgement embedded in reported profit.', false),
	('fsa-balance', 'fsa', 'Analyzing the Balance Sheet', 4, 3.00, 3.00, '2026-09-05 18:01:14.522749+00', 'fsa', 3, 3, 'Measurement bases, classification, and what the balance sheet does not show.', false),
	('fsa-cashflow', 'fsa', 'Analyzing the Statement of Cash Flows', 1, 4.00, 4.00, '2026-09-07 19:57:13.931703+00', 'fsa', 4, 4, 'Direct and indirect methods, the link between the three statements, and free cash flow.', false),
	('fsa-inventories', 'fsa', 'Inventories and Cost of Goods Sold', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'fsa', 3, 5, 'Cost flow assumptions, their effect on income and inventory, and write-downs.', false),
	('fsa-longlived', 'fsa', 'Long-Lived Assets', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'fsa', 3, 6, 'Capitalisation versus expensing, depreciation choices, impairment and derecognition.', false),
	('fsa-tax-debt', 'fsa', 'Income Taxes and Non-Current Liabilities', 1, 4.00, 4.00, '2026-09-07 19:57:13.931703+00', 'fsa', 4, 7, 'Deferred tax assets and liabilities, bond accounting, leases and pension basics.', false),
	('fsa-ratios', 'fsa', 'Ratio Analysis and Reporting Quality', 1, 4.00, 3.00, '2026-09-07 19:57:13.931703+00', 'fsa', 4, 8, 'Common-size and ratio analysis, DuPont decomposition, and signals of low-quality reporting.', false),
	('ci-structures', 'ci', 'Organisational Forms and Corporate Governance', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'ci', 2, 1, 'Business structures, the principal–agent problem, and governance mechanisms.', false),
	('ci-stakeholders', 'ci', 'Stakeholders and ESG Considerations', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'ci', 2, 2, 'Competing stakeholder claims and how ESG factors enter investment analysis.', false),
	('ci-investments', 'ci', 'Capital Investments and Project Analysis', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'ci', 3, 4, 'NPV, IRR, and why the two can disagree about the same project.', false),
	('ci-capstructure', 'ci', 'Capital Structure and Cost of Capital', 1, 4.00, 4.00, '2026-09-07 19:57:13.931703+00', 'ci', 4, 5, 'WACC, the effect of leverage, and the theories that explain observed structures.', false),
	('ci-measures', 'ci', 'Business Models and Corporate Measures', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'ci', 2, 6, 'How a business model shapes the numbers an analyst should expect to see.', false),
	('eq-markets', 'eq', 'Market Organisation and Structure', 1, 3.00, 2.00, '2026-09-07 19:57:13.931703+00', 'eq', 3, 1, 'Assets, intermediaries, order types, margin, and how trades actually happen.', false),
	('eq-indexes', 'eq', 'Security Market Indexes', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'eq', 2, 2, 'Weighting methods, rebalancing, and the consequences of index construction choices.', false),
	('eq-efficiency', 'eq', 'Market Efficiency', 1, 2.00, 3.00, '2026-09-07 19:57:13.931703+00', 'eq', 2, 3, 'Forms of efficiency, documented anomalies, and what they imply for active management.', false),
	('eq-features', 'eq', 'Equity Securities and Their Features', 1, 3.00, 2.00, '2026-09-07 19:57:13.931703+00', 'eq', 3, 4, 'Types of equity claim, private versus public, and the effect on risk and return.', false),
	('eq-industry', 'eq', 'Industry and Company Analysis', 1, 4.00, 3.00, '2026-09-07 19:57:13.931703+00', 'eq', 4, 5, 'Classifying an industry, competitive position, and building a revenue forecast.', false),
	('eq-dcf', 'eq', 'Discounted Dividend Valuation', 1, 4.00, 4.00, '2026-09-07 19:57:13.931703+00', 'eq', 4, 6, 'Dividend discount models including Gordon growth, and the sensitivity of the output to its inputs.', false),
	('eq-multiples', 'eq', 'Multiples and Asset-Based Valuation', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'eq', 3, 7, 'Price and enterprise multiples, comparables, and asset-based approaches.', false),
	('fi-features', 'fi', 'Fixed-Income Instruments and Features', 1, 3.00, 2.00, '2026-09-07 19:57:13.931703+00', 'fi', 3, 1, 'Bond structures, indentures, covenants, and embedded options.', false),
	('fi-issuance', 'fi', 'Issuance, Trading and Funding', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'fi', 2, 2, 'Primary and secondary markets, and how sovereigns, corporates and banks fund themselves.', false),
	('fi-pricing', 'fi', 'Bond Pricing and Yield Measures', 1, 4.00, 4.00, '2026-09-07 19:57:13.931703+00', 'fi', 4, 3, 'Pricing from cash flows, yield to maturity, and the conventions that trip candidates up.', false),
	('fi-curves', 'fi', 'Spot, Par and Forward Curves', 1, 4.00, 5.00, '2026-09-07 19:57:13.931703+00', 'fi', 4, 4, 'Deriving one curve from another, and reading what the shape implies.', false),
	('fi-yieldspreads', 'fi', 'Yield Spreads and Credit Analysis', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'fi', 3, 5, 'Spread measures, credit risk components, and the four Cs of credit.', false),
	('fi-duration', 'fi', 'Duration and Interest Rate Risk', 1, 4.00, 4.00, '2026-09-07 19:57:13.931703+00', 'fi', 4, 6, 'Macaulay, modified and effective duration, and estimating a price change from a rate move.', false),
	('fi-convexity', 'fi', 'Convexity and Portfolio Measures', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'fi', 3, 7, 'Second-order price effects, and duration and convexity at portfolio level.', false),
	('fi-securitised', 'fi', 'Asset-Backed and Securitised Products', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'fi', 3, 8, 'The securitisation process, tranching, and prepayment risk.', false),
	('deriv-intro', 'deriv', 'Derivative Instruments and Markets', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'deriv', 2, 1, 'What a derivative is, why they exist, and exchange-traded versus over-the-counter.', false),
	('deriv-forwards', 'deriv', 'Forwards and Futures', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'deriv', 3, 2, 'Forward commitments, marking to market, and the difference the exchange makes.', false),
	('deriv-swaps', 'deriv', 'Swaps and Their Uses', 1, 2.00, 3.00, '2026-09-07 19:57:13.931703+00', 'deriv', 2, 3, 'Swaps as a series of forwards, and the exposures they are used to change.', false),
	('deriv-options', 'deriv', 'Options and Payoff Structures', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'deriv', 3, 4, 'Calls and puts, moneyness, payoff and profit diagrams, and put–call parity.', false),
	('deriv-pricing', 'deriv', 'Arbitrage, Replication and Pricing', 1, 3.00, 5.00, '2026-09-07 19:57:13.931703+00', 'deriv', 3, 5, 'The no-arbitrage argument, replication, and binomial valuation. The hardest reasoning in the topic.', false),
	('alt-features', 'alt', 'Alternative Investment Features and Structures', 1, 3.00, 2.00, '2026-09-07 19:57:13.931703+00', 'alt', 3, 1, 'What separates alternatives from traditional assets, and how vehicles are structured.', false),
	('alt-pe', 'alt', 'Private Equity and Private Debt', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'alt', 3, 2, 'Buyouts, venture capital, private credit, and how returns are generated and measured.', false),
	('alt-realassets', 'alt', 'Real Estate and Infrastructure', 1, 3.00, 3.00, '2026-09-07 19:57:13.931703+00', 'alt', 3, 3, 'Direct and indirect property investment, REITs, and long-lived infrastructure assets.', false),
	('alt-hedge', 'alt', 'Hedge Fund Strategies', 1, 2.00, 3.00, '2026-09-07 19:57:13.931703+00', 'alt', 2, 4, 'Strategy families, leverage, and the risk characteristics each brings.', false),
	('alt-performance', 'alt', 'Performance, Fees and Due Diligence', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'alt', 3, 5, 'Management and incentive fees, hurdle rates and high-water marks, and reported-return caveats.', false),
	('pm-process', 'pm', 'The Portfolio Management Process', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'pm', 2, 1, 'Why a portfolio perspective changes the answer, and the steps of the process.', false),
	('pm-risk-return', 'pm', 'Risk, Return and the Efficient Frontier', 1, 4.00, 4.00, '2026-09-07 19:57:13.931703+00', 'pm', 4, 2, 'Portfolio risk and return, diversification, and the efficient frontier.', false),
	('pm-capm', 'pm', 'Capital Asset Pricing and Beta', 1, 3.00, 4.00, '2026-09-07 19:57:13.931703+00', 'pm', 3, 3, 'The capital market line, the security market line, beta, and CAPM''s assumptions.', false),
	('pm-planning', 'pm', 'Investor Profiles and the IPS', 1, 3.00, 2.00, '2026-09-07 19:57:13.931703+00', 'pm', 3, 4, 'Objectives and constraints, and turning a client situation into a policy statement.', false),
	('pm-behavioural', 'pm', 'Behavioural Biases in Investing', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'pm', 2, 5, 'Cognitive errors and emotional biases, and where they show up in portfolios.', false),
	('pm-fintech', 'pm', 'Technology and Analytics in Investment Management', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'pm', 2, 6, 'Data, algorithms and automation as they are used across the investment process.', false),
	('eth-framework', 'eth', 'Ethics and the Investment Profession', 1, 3.00, 2.00, '2026-09-07 19:57:13.931703+00', 'eth', 3, 1, 'Why the profession needs a code, and a framework for working through a dilemma.', false),
	('eth-standards-i-ii', 'eth', 'Professionalism and Market Integrity', 1, 4.00, 3.00, '2026-09-07 19:57:13.931703+00', 'eth', 4, 2, 'Knowledge of the law, independence, misrepresentation, misconduct, and material non-public information.', false),
	('eth-standards-iii-iv', 'eth', 'Duties to Clients and Employers', 1, 4.00, 3.00, '2026-09-07 19:57:13.931703+00', 'eth', 4, 3, 'Loyalty and care, fair dealing, suitability, confidentiality, and duties to an employer.', false),
	('eth-standards-v-vii', 'eth', 'Analysis, Conflicts and Programme Responsibilities', 1, 4.00, 3.00, '2026-09-07 19:57:13.931703+00', 'eth', 4, 4, 'Diligence, record retention, disclosure of conflicts, and responsibilities as a candidate.', false),
	('eth-gips', 'eth', 'Global Investment Performance Standards', 1, 2.00, 2.00, '2026-09-07 19:57:13.931703+00', 'eth', 2, 5, 'What GIPS is for, who can claim compliance, and the shape of its requirements.', false);
INSERT INTO public.curriculum_readings (id, reading_no, topic_id, title, sequence, start_page, page_count, effort_units, effort_band, summary, relevance, structure_pending, is_active, legacy_module_ids, created_at) VALUES
	('r026', 26, 'ci', 'Business Models', 7, 405, 6, 0.86, 2, 'Describes the key features and types of business models.', 'A short conceptual reading that tests classification.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r001', 1, 'quant', 'Returns of Financial Assets and Instruments', 1, 1, 14, 2.01, 3, 'Defines what a return is and how it is measured on financial assets, instruments and indicators. Builds the language of required return: the risk-free rate, risk premia and inflation.', 'The vocabulary of returns underpins every valuation and portfolio reading that follows.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r002', 2, 'quant', 'Types of Financial Returns', 2, 15, 12, 1.72, 3, 'Distinguishes the main types of returns across assets, instruments and indicators, and how each is calculated over short and long horizons.', 'Return conventions decide which formula an exam question expects.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r003', 3, 'quant', 'Benchmarking Returns', 3, 27, 23, 3.30, 4, 'Compares how portfolio performance and market indexes are measured: money-weighted versus time-weighted returns, and how index construction choices shape what an index shows.', 'Performance measurement and index design recur in portfolio and equity questions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r004', 4, 'quant', 'The Time Value of Money in Finance', 4, 50, 17, 2.44, 4, 'Applies discounted cash flow to value fixed-income and equity instruments, and derives implied returns and growth. Introduces cash flow additivity and no-arbitrage pricing.', 'Time value of money is the engine behind bond, equity and derivative pricing.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r005', 5, 'quant', 'Statistical Characteristics of Asset Returns', 5, 67, 22, 3.16, 4, 'Describes return data with measures of central tendency, dispersion, skewness, kurtosis, covariance and correlation.', 'Descriptive statistics feed risk measurement and hypothesis testing.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r006', 6, 'quant', 'Statistical Distributions for Financial Asset Prices and Returns', 6, 89, 26, 3.73, 4, 'Covers expected values, variances and the main probability distributions used for asset prices and returns, including conditional expectations and Bayesian updating.', 'Distribution choice and probability updates support risk and inference questions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r007', 7, 'quant', 'Estimation and Hypothesis Testing', 7, 115, 41, 5.89, 4, 'Explains sampling, the central limit theorem, confidence intervals and hypothesis testing, and how to choose between parametric and non-parametric tests.', 'Inference underpins performance evaluation and model validation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r008', 8, 'quant', 'The Return and Risk of a Financial Portfolio', 8, 156, 35, 5.03, 4, 'Calculates portfolio return and risk, shows how correlation drives diversification, and builds the efficient frontier, capital allocation line and CAPM.', 'Portfolio theory links quantitative methods to portfolio management and equity valuation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r009', 9, 'quant', 'Simulation of Financial Asset Prices and Returns', 9, 191, 12, 1.72, 3, 'Introduces simulation as a way to model uncertain outcomes: historical simulation, bootstrap resampling and Monte Carlo.', 'Simulation appears in risk and valuation applications.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r010', 10, 'quant', 'Applications of Simple Linear Regression in Finance', 10, 203, 26, 3.73, 4, 'Uses simple linear regression to relate variables in finance: estimation, assumptions, goodness of fit, prediction intervals and CAPM estimation.', 'Regression interpretation is a frequent calculation and reasoning topic.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r011', 11, 'quant', 'Introduction to Financial Data Science', 11, 229, 12, 1.72, 3, 'Introduces big data, machine learning, artificial intelligence and fintech as they apply to investment management.', 'A newer topic that tests concepts and applications rather than calculation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r012', 12, 'econ', 'The Firm and Market Structures', 1, 241, 24, 3.45, 4, 'Explains how firms decide output and pricing under different market structures, using breakeven, shutdown and scale ideas, and how structure and concentration are identified.', 'Market structure links firm behaviour to industry analysis in equity.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r013', 13, 'econ', 'Understanding Business Cycles', 2, 265, 10, 1.44, 3, 'Describes the business cycle and its phases, credit cycles, and how activity across sectors varies over the cycle and is measured.', 'Cycle awareness supports asset allocation and industry analysis.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r014', 14, 'econ', 'Fiscal Policy', 3, 275, 12, 1.72, 3, 'Compares fiscal with monetary policy, its objectives and tools, the debt debate, and whether a stance is expansionary or contractionary.', 'Policy stance questions test interpretation of economic conditions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r015', 15, 'econ', 'Monetary Policy', 4, 287, 12, 1.72, 3, 'Covers central bank objectives and tools, the monetary transmission mechanism, inflation targeting and the limits of monetary policy.', 'Monetary policy drives rates, currencies and asset prices.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r016', 16, 'econ', 'Introduction to Geopolitics', 5, 299, 10, 1.44, 3, 'Introduces geopolitics: cooperation versus competition, globalization, international organizations, geopolitical risk and its effect on investments.', 'Geopolitical risk is a new theme linking economics to investment decisions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r017', 17, 'econ', 'International Trade', 6, 309, 10, 1.44, 3, 'Explains the benefits and costs of international trade, trade restrictions and the trading blocs and unions that shape it.', 'Trade concepts support currency and country analysis.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r018', 18, 'econ', 'Capital Flows and the FX Market', 7, 319, 12, 1.72, 3, 'Describes the foreign exchange market, exchange rate regimes and their effects, and capital restrictions imposed by governments.', 'FX regime knowledge connects economics to international investing.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r019', 19, 'econ', 'Exchange Rate Calculations', 8, 331, 10, 1.44, 3, 'Teaches exchange rate calculations: cross rates, no-arbitrage relationships, forward rates, points and premium or discount.', 'A calculation-heavy reading with predictable question formats.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r020', 20, 'ci', 'Organizational Forms, Corporate Issuer Features, and Ownership', 1, 341, 8, 1.15, 2, 'Compares organizational forms of business and the features of corporate issuers, including public versus private ownership.', 'Foundation for corporate governance and capital structure readings.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r021', 21, 'ci', 'Investors and Other Stakeholders', 2, 349, 8, 1.15, 2, 'Compares the claims and motivations of lenders and shareholders, other stakeholder groups, and the ESG factors investors consider.', 'Stakeholder and ESG framing appears in governance and valuation contexts.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r022', 22, 'ci', 'Corporate Governance: Conflicts, Mechanisms, Risks, and Benefits', 3, 357, 10, 1.44, 3, 'Explains principal-agent conflicts, governance mechanisms, and the risks of poor governance and benefits of effective governance.', 'Governance questions test identification of conflicts and mitigants.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r023', 23, 'ci', 'Working Capital and Liquidity', 4, 367, 10, 1.44, 3, 'Covers the cash conversion cycle, liquidity levels and the management of working capital.', 'Working capital feeds ratio analysis and credit assessment.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r024', 24, 'ci', 'Capital Investments and Capital Allocation', 5, 377, 14, 2.01, 3, 'Covers types of capital investment, NPV, IRR and ROIC, capital allocation principles and pitfalls, and real options.', 'Capital budgeting calculations are a staple of corporate finance questions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r025', 25, 'ci', 'Capital Structure', 6, 391, 14, 2.01, 3, 'Calculates and interprets the weighted-average cost of capital and explains capital structure theories including Modigliani-Miller.', 'Cost of capital links corporate finance to valuation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r027', 27, 'fsa', 'Introduction to Financial Statement Analysis', 1, 1, 12, 1.72, 3, 'Introduces the financial statement analysis framework, the roles of analysis, the information in filings, notes and audit reports, and how reporting standards develop.', 'The frame every later financial statement reading assumes.', false, true, '{fsa-intro}', '2026-09-19 12:59:06.959086+00'),
	('r028', 28, 'fsa', 'Analyzing Income Statements', 2, 13, 36, 5.17, 4, 'Analyzes income statements: revenue and expense recognition, non-recurring items, basic and diluted earnings per share, and common-size analysis.', 'Income statement analysis is high-yield for both calculation and judgement.', false, true, '{fsa-income}', '2026-09-19 12:59:06.959086+00'),
	('r029', 29, 'fsa', 'Analyzing Balance Sheets', 3, 49, 16, 2.30, 4, 'Analyzes balance sheets: intangible assets, goodwill, financial instruments, non-current liabilities and common-size balance sheets.', 'Balance sheet quality affects ratios and valuation.', false, true, '{fsa-balance}', '2026-09-19 12:59:06.959086+00'),
	('r030', 30, 'fsa', 'Analyzing Statements of Cash Flows I', 4, 65, 30, 4.31, 4, 'Explains how the cash flow statement links to the other statements, direct versus indirect preparation, and IFRS versus US GAAP differences.', 'Cash flow presentation questions test conversion and classification.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r031', 31, 'fsa', 'Analyzing Statements of Cash Flows II', 5, 95, 10, 1.44, 3, 'Analyzes cash flow statements: free cash flow to the firm and to equity, and cash flow ratios.', 'Free cash flow is central to valuation and credit analysis.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r032', 32, 'fsa', 'Analysis of Inventories', 6, 105, 20, 2.87, 4, 'Covers inventory measurement, the effect of FIFO and LIFO in inflation and deflation, and presentation and disclosure.', 'Inventory method effects are a classic comparison topic.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r033', 33, 'fsa', 'Analysis of Long-Term Assets', 7, 125, 18, 2.59, 4, 'Compares reporting of purchased, internally developed and acquired assets, impairment and derecognition, and long-term asset disclosures.', 'Asset accounting choices change reported profit and ratios.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r034', 34, 'fsa', 'Topics in Long-Term Liabilities and Equity', 8, 143, 24, 3.45, 4, 'Covers lease reporting from both sides, defined contribution and benefit plans, share-based compensation and related disclosures.', 'Liability and equity items alter leverage and earnings quality.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r035', 35, 'fsa', 'Analysis of Income Taxes', 9, 167, 22, 3.16, 4, 'Explains differences between accounting profit and taxable income, deferred tax assets and liabilities, tax rates and disclosures.', 'Deferred tax treatment is a recurring analytical issue.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r036', 36, 'fsa', 'Financial Reporting Quality', 10, 189, 18, 2.59, 4, 'Assesses financial reporting quality: the spectrum from conservative to aggressive, earnings management and warning signs of manipulation.', 'Reporting quality supports judgement questions across statements.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r037', 37, 'fsa', 'Financial Analysis Techniques', 11, 207, 30, 4.31, 4, 'Applies ratio analysis: activity, liquidity, solvency and profitability, DuPont decomposition, industry-specific ratios and forecasting.', 'One of the most heavily tested financial statement readings.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r038', 38, 'fsa', 'Introduction to Financial Statement Modeling', 12, 237, 12, 1.72, 3, 'Builds a sales-based pro forma model and considers behavioral factors, competitive position and forecast horizon.', 'Modeling links analysis to valuation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r039', 39, 'eq', 'Equity Instrument Features', 1, 249, 6, 0.86, 2, 'Describes basic features and types of equity instruments and contrasts public with private equity.', 'Foundation for equity markets and valuation readings.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r040', 40, 'eq', 'Equity Jurisdictions, Classes, and the Voting Process', 2, 255, 6, 0.86, 2, 'Explains economic and voting rights across jurisdictions and share classes, and the voting process and its participants.', 'Ownership rights matter for governance and valuation questions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r041', 41, 'eq', 'Equity Issuance and Trading', 3, 261, 12, 1.72, 3, 'Describes equity markets, exchanges and trading venues, liquidity measures and types of equity indexes.', 'Market structure knowledge supports execution and index questions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r042', 42, 'eq', 'Sources of Equity Returns', 4, 273, 10, 1.44, 3, 'Explains dividends, share repurchases and splits, and calculates price and total return for equities.', 'Return calculations from corporate actions appear in many questions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r043', 43, 'eq', 'Introduction to Equity Valuation', 5, 283, 12, 1.72, 3, 'Contrasts price with intrinsic value, book value with market capitalization and enterprise value, and outlines the main valuation models.', 'Frames every valuation approach that follows.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r044', 44, 'eq', 'Discounted Cash Flow (DCF) and Growth Models', 6, 295, 18, 2.59, 4, 'Values equity using discounted cash flow: dividend, FCFF, FCFE and residual income models, constant and multistage growth, and preferred stock.', 'Discounted cash flow valuation is a core calculation topic.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r045', 45, 'eq', 'Relative Value Equity Valuation Approaches', 7, 313, 18, 2.59, 4, 'Values equity with multiples: price and enterprise value multiples, peer groups and comparable-based valuation.', 'Relative valuation is widely tested for method and interpretation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r046', 46, 'eq', 'Financial Statement Forecasting in Equity Valuation', 8, 331, 12, 1.72, 3, 'Explains how to construct and evaluate financial statement forecast models for equity valuation.', 'Bridges financial statement analysis and valuation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r047', 47, 'eq', 'Industry and Competitive Analysis', 9, 343, 16, 2.30, 4, 'Describes industry analysis: classification, size, growth and profitability, and structure through Porter''s Five Forces and PESTLE.', 'Industry analysis frameworks are common in equity questions.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r048', 48, 'eq', 'Company Analysis: Past, Present, and Future', 10, 359, 16, 2.30, 4, 'Evaluates a company''s strategy and position, revenue drivers, profitability and pricing power, working capital and capital structure.', 'Company analysis ties strategy to financial performance.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r049', 49, 'eq', 'Equity Analyst Research Reports', 11, 375, 12, 1.72, 3, 'Describes the elements of an equity analyst research report and compares sell-side with buy-side views.', 'Tests reading and evaluating research rather than calculation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r050', 50, 'eq', 'The Capital Asset Pricing Model, Market Model, and Other Factor-Based Equity Models', 12, 387, 11, 1.58, 3, 'Estimates the cost of equity with the CAPM and market model, and introduces arbitrage pricing theory and multi-factor models.', 'Required return estimation is an input to many valuations.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r051', 51, 'fi', 'Fixed-Income Instrument Features', 1, 1, 8, 1.15, 2, 'Describes the features of a fixed-income security and the contents of a bond indenture, including covenants.', 'The vocabulary of bonds for the rest of fixed income.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r052', 52, 'fi', 'Fixed-Income Cash Flows and Types', 2, 9, 12, 1.72, 3, 'Explains fixed-income cash flow structures, contingency provisions, and the legal, regulatory and tax factors that affect issuance and trading.', 'Cash flow structure decides valuation method.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r053', 53, 'fi', 'Fixed-Income Issuance and Trading', 3, 21, 10, 1.44, 3, 'Describes fixed-income market segments and participants, index types, and primary versus secondary markets.', 'Market structure context for pricing.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r054', 54, 'fi', 'Fixed-Income Markets for Corporate Issuers', 4, 31, 10, 1.44, 3, 'Compares short- and long-term funding for corporate issuers, including repurchase agreements, and investment-grade versus high-yield funding.', 'Links corporate funding choices to bond markets.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r055', 55, 'fi', 'Fixed-Income Markets for Government Issuers', 5, 41, 8, 1.15, 2, 'Describes funding by sovereign, non-sovereign and supranational issuers and contrasts government with corporate issuance and trading.', 'Government issuance context for credit analysis.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r056', 56, 'fi', 'Fixed-Income Bond Valuation: Prices and Yields', 6, 49, 12, 1.72, 3, 'Values a bond from yield to maturity, explains price relationships and matrix pricing.', 'Bond pricing calculations are essential and frequently tested.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r057', 57, 'fi', 'Yield and Yield Spread Measures for Fixed-Rate Bonds', 7, 61, 12, 1.72, 3, 'Calculates yields and yield spreads for fixed-rate bonds and interprets them.', 'Yield measures decide relative value.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r058', 58, 'fi', 'Yield and Yield Spread Measures for Floating-Rate Instruments', 8, 73, 6, 0.86, 2, 'Calculates spreads and yields for floating-rate instruments and money market instruments.', 'A distinct calculation set that differs from fixed-rate bonds.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r059', 59, 'fi', 'The Term Structure of Interest Rates: Spot, Par, and Forward Curves', 9, 79, 12, 1.72, 3, 'Explains spot, par and forward rates, prices bonds from spot rates, and compares the curves.', 'The term structure underpins bond and derivative valuation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r060', 60, 'fi', 'Interest Rate Risk and Return', 10, 91, 10, 1.44, 3, 'Analyzes sources of return on a fixed-rate bond, holding period return and Macaulay duration.', 'Bridges pricing and interest rate risk.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r061', 61, 'fi', 'Yield-Based Bond Duration Measures and Properties', 11, 101, 8, 1.15, 2, 'Defines and calculates modified duration, money duration and price value of a basis point, and what drives interest rate risk.', 'Duration is among the most tested fixed-income topics.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r062', 62, 'fi', 'Yield-Based Bond Convexity and Portfolio Properties', 12, 109, 12, 1.72, 3, 'Calculates convexity and combines duration and convexity to estimate price change, including at portfolio level.', 'Improves price-change estimates beyond duration.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r063', 63, 'fi', 'Curve-Based and Empirical Fixed-Income Risk Measures', 13, 121, 8, 1.15, 2, 'Uses effective duration and convexity for bonds with options, key rate duration, and empirical versus analytical duration.', 'Extends risk measures to callable and complex bonds.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r064', 64, 'fi', 'Credit Risk', 14, 129, 12, 1.72, 3, 'Describes credit risk and its components, uses and limits of ratings, and drivers of yield spreads.', 'Credit risk framing for corporate and government analysis.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r065', 65, 'fi', 'Credit Analysis for Government Issuers', 15, 141, 6, 0.86, 2, 'Explains special considerations in evaluating sovereign and non-sovereign government credit.', 'Distinct credit factors from corporate analysis.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r066', 66, 'fi', 'Credit Analysis for Corporate Issuers', 16, 147, 10, 1.44, 3, 'Describes qualitative and quantitative factors in corporate credit analysis, seniority rankings and claims priority.', 'Applies financial ratios to creditworthiness.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r067', 67, 'fi', 'Fixed-Income Securitization', 17, 157, 8, 1.15, 2, 'Explains the benefits of securitization and the parties and roles involved.', 'Foundation for ABS and MBS readings.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r068', 68, 'fi', 'Asset-Backed Security (ABS) Instrument and Market Features', 18, 165, 8, 1.15, 2, 'Describes covered bonds, credit enhancement, non-mortgage ABS and collateralized debt obligations.', 'Structure and risk of asset-backed products.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r069', 69, 'fi', 'Mortgage-Backed Security (MBS) Instrument and Market Features', 19, 173, 14, 2.01, 3, 'Explains prepayment risk, tranching, residential mortgage loans and commercial and residential mortgage-backed securities.', 'Prepayment risk is the key MBS concept.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r070', 70, 'deriv', 'Derivative Instrument and Derivative Market Features', 1, 187, 10, 1.44, 3, 'Defines a derivative, describes derivative markets and contrasts over-the-counter with exchange-traded contracts.', 'Sets the vocabulary of derivatives.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r071', 71, 'deriv', 'Forward Commitment and Contingent Claim Features and Instruments', 2, 197, 12, 1.72, 3, 'Defines forwards, futures, swaps, options and credit derivatives, determines option value at expiration, and contrasts forward commitments with contingent claims.', 'Payoff reasoning underpins pricing readings.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r072', 72, 'deriv', 'Derivative Benefits, Risks, and Issuer and Investor Uses', 3, 209, 8, 1.15, 2, 'Describes the benefits and risks of derivatives and how issuers and investors use them.', 'Applications and risk framing for derivatives.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r073', 73, 'deriv', 'Arbitrage, Replication, and the Cost of Carry in Pricing Derivatives', 4, 217, 8, 1.15, 2, 'Explains arbitrage, replication and cost of carry as foundations of derivative pricing.', 'No-arbitrage logic is the basis of every pricing model.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r074', 74, 'deriv', 'Pricing and Valuation of Forward Contracts and for an Underlying with Varying Maturities', 5, 225, 8, 1.15, 2, 'Values forward contracts at initiation, during their life and at expiration, and explains how forward rates are determined.', 'Forward valuation calculations are tested regularly.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r075', 75, 'deriv', 'Pricing and Valuation of Futures Contracts', 6, 233, 6, 0.86, 2, 'Compares the value and price of forward and futures contracts and explains why they differ.', 'Clarifies a common source of confusion.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r076', 76, 'deriv', 'Pricing and Valuation of Interest Rates and Other Swaps', 7, 239, 6, 0.86, 2, 'Explains how swaps resemble and differ from forward contracts and how swaps are priced and valued.', 'Swap valuation extends forward pricing.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r077', 77, 'deriv', 'Pricing and Valuation of Options', 8, 245, 10, 1.44, 3, 'Explains exercise value, moneyness and time value, and the factors that determine an option''s value.', 'Option value drivers are frequent testing points.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r078', 78, 'deriv', 'Option Replication Using Put-Call Parity', 9, 255, 8, 1.15, 2, 'Explains put-call parity and put-call forward parity for European options.', 'Parity relationships are a common calculation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r079', 79, 'deriv', 'Valuing a Derivative Using a One-Period Binomial Model', 10, 263, 9, 1.29, 3, 'Values a derivative with a one-period binomial model and explains risk neutrality.', 'A compact calculation topic.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r080', 80, 'alt', 'Alternative Investment Features, Methods, and Structures', 1, 1, 10, 1.44, 3, 'Describes features and categories of alternative investments, the ways to invest in them and their ownership and compensation structures.', 'Sets the frame for alternative asset classes.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r081', 81, 'alt', 'Alternative Investment Performance and Returns', 2, 11, 12, 1.72, 3, 'Describes performance appraisal of alternative investments and calculates returns before and after fees.', 'Fee-adjusted returns are the testable calculation.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r082', 82, 'alt', 'Investments in Private Capital: Equity and Debt', 3, 23, 8, 1.15, 2, 'Explains private equity and private debt features and the diversification benefits of private capital.', 'Private markets characteristics and role in portfolios.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r083', 83, 'alt', 'Real Estate and Infrastructure', 4, 31, 8, 1.15, 2, 'Explains the features and investment characteristics of real estate and infrastructure.', 'Real assets and their return drivers.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r084', 84, 'alt', 'Natural Resources', 5, 39, 6, 0.86, 2, 'Explains raw land, timberland, farmland and commodities and analyzes their risk, return and diversification.', 'Natural resources as portfolio diversifiers.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r085', 85, 'alt', 'Hedge Funds', 6, 45, 8, 1.15, 2, 'Explains hedge fund features, forms and vehicles, and analyzes risk, return and diversification.', 'Hedge fund characteristics versus other assets.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r086', 86, 'alt', 'Introduction to Digital Assets', 7, 53, 16, 2.30, 4, 'Introduces distributed ledger technology and digital assets, their forms and vehicles, and their risk, return and diversification.', 'A newer topic emphasizing concepts.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r087', 87, 'pm', 'Portfolio Risk and Return: Part I', 1, 69, 18, 2.59, 4, 'Covers asset-class characteristics, risk aversion and utility, mean, variance and covariance from historical data, portfolio standard deviation, and the efficient frontiers.', 'Core portfolio theory with calculation elements.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r088', 88, 'pm', 'Portfolio Risk and Return: Part II', 2, 87, 26, 3.73, 4, 'Combines a risk-free asset with risky assets, explains systematic and nonsystematic risk, beta, the CAPM and SML, and performance ratios.', 'CAPM and performance measures are high-yield.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r089', 89, 'pm', 'Portfolio Management: An Overview', 3, 113, 14, 2.01, 3, 'Describes the portfolio approach, the portfolio management process, investor types, pension plans and pooled investments.', 'Frames the management process and client types.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r090', 90, 'pm', 'Basics of Portfolio Planning and Construction', 4, 127, 14, 2.01, 3, 'Explains the investment policy statement, risk and return objectives, constraints, asset allocation and ESG considerations.', 'IPS construction is a common case-style topic.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r091', 91, 'pm', 'The Behavioral Biases of Individuals', 5, 141, 16, 2.30, 4, 'Compares cognitive errors with emotional biases and their implications for financial decisions.', 'Bias identification is tested through scenarios.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r092', 92, 'pm', 'Introduction to Risk Management', 6, 157, 12, 1.72, 3, 'Defines risk management and its framework, governance, risk tolerance, budgeting, risk sources and methods of measuring and modifying risk.', 'Introduces enterprise and portfolio risk concepts.', false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r093', 93, 'eth', 'Ethics and Trust in the Investment Profession', 1, 169, 8, 1.15, 2, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r094', 94, 'eth', 'Code of Ethics and Standards of Professional Conduct', 2, 177, 8, 1.15, 2, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r095', 95, 'eth', 'Guidance for Standard I: Professionalism', 3, 185, 8, 1.15, 2, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r096', 96, 'eth', 'Guidance for Standard II: Integrity of Capital Markets', 4, 193, 4, 0.57, 1, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r097', 97, 'eth', 'Guidance for Standard III: Duties to Clients', 5, 197, 8, 1.15, 2, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r098', 98, 'eth', 'Guidance for Standard IV: Duties to Employers', 6, 205, 6, 0.86, 2, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r099', 99, 'eth', 'Guidance for Standard V: Investment Analysis, Recommendations, and Actions', 7, 211, 6, 0.86, 2, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r100', 100, 'eth', 'Guidance for Standard VI: Conflicts of Interest', 8, 217, 6, 0.86, 2, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
	('r101', 101, 'eth', 'Guidance for Standard VII: Responsibilities as a CFA Institute Member or CFA Candidate', 9, 223, 4, 0.57, 1, NULL, NULL, false, true, '{}', '2026-09-19 12:59:06.959086+00'),
